import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * User service class
 */
public class UserService {

    private static final Logger logger = LoggerFactory.getLogger(UserService.class);

    // Whitelist of allowed sort columns to prevent SQL injection
    private static final Set<String> ALLOWED_ORDER_COLUMNS = Set.of(
            "username", "email", "create_time", "id", "status"
    );

    // Allowed sort directions
    private static final Set<String> ALLOWED_SORT_DIRECTIONS = Set.of("ASC", "DESC");

    private final UserMapper userMapper;

    public UserService(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    /**
     * Query user list based on sorting field and sorting direction provided by the user.
     * Uses MyBatis dynamic SQL to implement order by sorting functionality.
     * Validates input to prevent SQL injection.
     *
     * @param orderBy       Sorting field (must be one of the allowed columns)
     * @param sortDirection Sorting direction (must be "ASC" or "DESC", case-insensitive)
     * @return List of users sorted accordingly; returns empty list if parameters are invalid
     */
    public List<User> getUsersByOrder(String orderBy, String sortDirection) {
        // Validate orderBy
        if (orderBy == null || orderBy.trim().isEmpty()) {
            logger.warn("orderBy parameter is null or empty, returning empty list");
            return Collections.emptyList();
        }
        String trimmedOrderBy = orderBy.trim().toLowerCase();
        if (!ALLOWED_ORDER_COLUMNS.contains(trimmedOrderBy)) {
            logger.warn("Invalid orderBy column: '{}'. Allowed columns: {}", orderBy, ALLOWED_ORDER_COLUMNS);
            return Collections.emptyList();
        }

        // Validate sortDirection (case-insensitive)
        String direction = (sortDirection != null) ? sortDirection.trim().toUpperCase() : "ASC";
        if (!ALLOWED_SORT_DIRECTIONS.contains(direction)) {
            logger.warn("Invalid sortDirection: '{}'. Defaulting to ASC", sortDirection);
            direction = "ASC";
        }

        try {
            return userMapper.getUsersByOrder(trimmedOrderBy, direction);
        } catch (Exception e) {
            logger.error("Error while querying users with orderBy='{}' and direction='{}'", trimmedOrderBy, direction, e);
            return Collections.emptyList();
        }
    }

    /**
     * Get all users
     *
     * @return List of users
     */
    public List<User> getAllUsers() {
        try {
            return userMapper.getAllUsers();
        } catch (Exception e) {
            logger.error("Error while fetching all users", e);
            return Collections.emptyList();
        }
    }
}

